import { useState } from "react";

const Company = () => {
  const [message, setMessage] = useState('');
  const [messageType, setMessageType] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [CompanyName, setCompanyName] = useState('');
  const [Phonenumber, setPhonenumber] = useState('');
      const [EmailAddress, setEmailAddress] = useState(() => JSON.parse(localStorage.getItem('authUser') || 'null')?.email || '');
     const [Companylocation, setCompanylocation] = useState('');
     const [Companytype, setCompanytype] = useState('');
  const [WorkField, setWorkField] = useState('');
  const [Numberofemployees, setNumberofemployees] = useState('');
  const [Companydiscription, setCompanydiscription] = useState('');

 const handleSubmit = (e) => {
    e.preventDefault();
    setMessage('');
    setMessageType('');
    setIsSubmitting(true);
    const company = {CompanyName, Phonenumber,EmailAddress, Companylocation,Companytype,WorkField,Numberofemployees,Companydiscription };
    const authUser = JSON.parse(localStorage.getItem('authUser') || 'null');

    fetch('http://localhost:5000/Companies/', {
      method: 'POST',
      headers: { "Content-Type": "application/json", Authorization: authUser ? authUser.token : '' },
      body: JSON.stringify(company)
    })
    .then(async (response) => {
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.message || 'Failed to save company');
      }
      return data;
    })
    .then((data) => {
      console.log('Company saved:', data);
      setMessage('Your company registration was completed successfully.');
      setMessageType('success');
    })
    .catch((error) => {
      console.error('Company registration error:', error);
      setMessage(`Registration failed: ${error.message}`);
      setMessageType('error');
    })
    .finally(() => {
      setIsSubmitting(false);
    });
  }
 return (
    <div className="company">
      <h2>Create Your Company Account </h2>
      <p className="company-intro">Register your company and connect with talented professionals.</p>
      {message && (
        <div className={`company-message ${messageType}`} role="alert">
          {message}
        </div>
      )}
      <form onSubmit={handleSubmit}>
        <label>Company Name</label>
        <input 
          type="text" 
          placeholder="Enter your company name"
          required 
          value={CompanyName}
          onChange={(e) => setCompanyName(e.target.value)}
        />
         <label>Phone Number:</label>
        <input 
          type="tel" 
          placeholder="Enter your phone number"
          inputMode="tel"
          required 
          value={Phonenumber}
          onChange={(e) => setPhonenumber(e.target.value)}
        />
         <label>Email Address:</label>
        <input 
          type="email" 
          placeholder="Enter your company email address"
          required 
          value={EmailAddress}
          onChange={(e) => setEmailAddress(e.target.value)}
          readOnly={Boolean(JSON.parse(localStorage.getItem('authUser') || 'null'))}
        />
         <label>Company Location:</label>
        <input 
          type="text" 
          placeholder="Enter Your Company location"
          required 
          value={Companylocation}
          onChange={(e) => setCompanylocation(e.target.value)}
        />
         <label>Company Type:</label>
        <input 
          type="text" 
          placeholder="e.g. Technology,Healthcare,Construction.."
          required 
          value={Companytype}
          onChange={(e) => setCompanytype(e.target.value)}
        />
          <label>Work Field:</label>
          <select
            required
            value={WorkField}
            onChange={(e) => setWorkField(e.target.value)}
          >
            <option value="">Choose the work field</option>
            <option value="Doctor">Doctor</option>
            <option value="Nurse">Nurse</option>
            <option value="Software Developer">Software Developer</option>
            <option value="IT Specialist">IT Specialist</option>
            <option value="Civil Engineer">Civil Engineer</option>
            <option value="Mechanical Engineer">Mechanical Engineer</option>
            <option value="Teacher">Teacher</option>
            <option value="Business Manager">Business Manager</option>
            <option value="Lawyer">Lawyer</option>
            <option value="Pharmacist">Pharmacist</option>
            <option value="Banker">Banker</option>
            <option value="Graphic Designer">Graphic Designer</option>
            <option value="Digital Marketer">Digital Marketer</option>
            <option value="Driver">Driver</option>
            <option value="Chef">Chef</option>
            <option value="Architect">Architect</option>
            <option value="Journalist">Journalist</option>
          </select>
        <label>Number Of Employees:</label>
        <input 
          type="text"
          placeholder="e.g. 10-50 employees" 
          required 
          value={Numberofemployees}
          onChange={(e) => setNumberofemployees(e.target.value)}
        />
     <label>Company Discription</label>
     <textarea
       required
       placeholder="Tell us about your company"
          value={Companydiscription}
          onChange={(e) => setCompanydiscription(e.target.value)}>
 </textarea>
 <br></br>
        <button type="submit" disabled={isSubmitting}>
          {isSubmitting ? 'Submitting...' : 'Submit'}
        </button>
      </form>
    </div>
  );
}

export default Company ;
